    /// Search text: a token symbol ("PEPE"), pair ("ETH/USDC"), pool address,
    /// or token address.
    pub query: String,
    /// Network ID to restrict results (e.g. "eth", "base"). Omit to search
    /// all networks.
    pub network: Option<String>,
